import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import { marked } from "marked";

export type Book = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
};

const dir = path.join(process.cwd(), "content", "books");

async function readBook(file: string) {
  const raw = await fs.readFile(path.join(dir, file), "utf8");
  const { data, content } = matter(raw);
  const book: Book = {
    slug: file.replace(/\.md$/, ""),
    title: String(data.title),
    author: String(data.author),
    year: Number(data.year),
    rating: Number(data.rating),
    tags: (data.tags ?? []).map(String),
  };
  return { book, content };
}

export async function getBooks(): Promise<Book[]> {
  const files = (await fs.readdir(dir)).filter((f) => f.endsWith(".md"));
  const books = await Promise.all(files.map(async (f) => (await readBook(f)).book));
  return books.sort((a, b) => a.title.localeCompare(b.title));
}

export async function getBook(slug: string) {
  if (!/^[\w-]+$/.test(slug)) return null;
  try {
    const { book, content } = await readBook(`${slug}.md`);
    return { book, html: await marked.parse(content) };
  } catch {
    return null;
  }
}

export async function getTopRated(n: number) {
  const books = await getBooks();
  return books
    .sort((a, b) => b.rating - a.rating || a.title.localeCompare(b.title))
    .slice(0, n);
}
