"use client";
import Link from "next/link";
import { useState } from "react";
import type { Book } from "@/lib/books";
import { useFavorites } from "@/lib/favorites";

export default function BookList({ books, tags }: { books: Book[]; tags: string[] }) {
  const [selected, setSelected] = useState<string | null>(null);
  const favs = useFavorites();
  const shown = selected ? books.filter((b) => b.tags.includes(selected)) : books;
  return (
    <>
      <div role="group" aria-label="Filter by tag">
        <button type="button" aria-pressed={selected === null} onClick={() => setSelected(null)}>All</button>
        {tags.map((t) => (
          <button key={t} type="button" aria-pressed={selected === t} onClick={() => setSelected(t)}>{t}</button>
        ))}
      </div>
      <ul aria-label="Books">
        {shown.map((b) => (
          <li key={b.slug}>
