export type ContactState = { values: Fields; errors: Errors; success?: string };

export async function send(_prev: ContactState, formData: FormData): Promise<ContactState> {
  const get = (k: string) => String(formData.get(k) ?? "").trim();
  const values = { name: get("name"), email: get("email"), message: get("message") };
  const errors = validate(values);
